using System.Collections.Generic;
using System.Linq;
using SIL.LCModel;

namespace SIL.FieldWorks.XWorks.MorphologyEditor
{
	/// <summary>
	/// Exclude all auto-generated feature-based natural classes from the NC record list.
	/// </summary>
	public class NaturalClassRecordList : RecordList
	{
		protected override IEnumerable<int> GetObjectSet()
		{
			return ExcludeAutoGenerated(base.GetObjectSet(), m_cache);
		}

		/// <summary>
		/// The given natural class HVOs, less the feature-based classes generated automatically
		/// for a rule.
		/// </summary>
		internal static IEnumerable<int> ExcludeAutoGenerated(IEnumerable<int> hvos, LcmCache cache)
		{
			var repo = cache.ServiceLocator.GetInstance<ICmObjectRepository>();
			return hvos.Where(hvo =>
				!RuleFormulaControl.IsAutoGeneratedNaturalClass(repo.GetObject(hvo) as IPhNaturalClass));
		}
	}
}
